sysauto_script.script:
(function executeJob() {
    var grAggregate = new GlideAggregate('alm_hardware');
    var output = "Anzahl der Assets pro Modell (mit leerem Company-Feld):\n";

    grAggregate.addNullQuery('company');
    grAggregate.addNotNullQuery('model');
    grAggregate.addQuery('install_status', 6); // Status "In stock"


    grAggregate.groupBy('model');
    grAggregate.addAggregate('COUNT');
    grAggregate.query();

    while (grAggregate.next()) {
        var modelName = grAggregate.getDisplayValue('model'); // Anzeigename des Modells
        if (!modelName || modelName.trim() === "") {
            continue; 
        }

        var count = parseInt(grAggregate.getAggregate('COUNT'), 10); // Anzahl der Records als Integer

        output += "Modell: " + modelName + " - Anzahl: " + count + "\n";

        // Überprüfen, ob ein Eintrag mit dem gleichen Modellnamen in der problem-Tabelle existiert
        var existingProblem = new GlideRecord('problem');
        existingProblem.addQuery('short_description', "order \"" + modelName + "\"");
        existingProblem.query();

        if (count < 3) {
            if (!existingProblem.hasNext()) {
                var grProblem = new GlideRecord('problem');
                grProblem.initialize();
                grProblem.short_description = "order \"" + modelName + "\"";
                grProblem.state = 1; // Status "open"
                grProblem.insert();


                gs.eventQueue("x_sigh_a_a_portal.custom.asset_notificat", null, modelName, count);
            } else { 
                while (existingProblem.next()) {
                    if (existingProblem.state == 4) { 
                        existingProblem.state = 1; 
                        existingProblem.update();

                        gs.eventQueue("x_sigh_a_a_portal.custom.asset_notificat", null, modelName, count);
                    }
                }
            }
        } else {
            // Wenn mehr oder genau 3 Assets vorhanden sind
            while (existingProblem.next()) {
                if (existingProblem.state == 1) { 
                    existingProblem.state = 4; 
                    existingProblem.update();
                }
            }
        }
    }

    gs.info(output);
})();
